"use client";

import Link from "next/link";
import { FormEvent, useState } from "react";
import { useParams } from "next/navigation";
import {
  ApiError,
  assignScheduleSlot,
  createScheduleSession,
  recordScheduleIncident,
  type ScheduleAssignmentOut,
  type ScheduleIncidentOut,
  type ScheduleSessionOut,
} from "@/lib/api";
import {
  ApiErrorAlert,
  FieldMessage,
  fieldErrorMap,
} from "@/components/forms/ApiErrorAlert";
import { PageHeader } from "@/components/layout/PageHeader";
import { PageShell } from "@/components/layout/PageShell";
import { StatusBadge } from "@/components/layout/StatusBadge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

export default function AdminSchedulePage() {
  const params = useParams<{ id: string }>();
  const competitionId = params.id;

  const [error, setError] = useState<ApiError | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [pending, setPending] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  const [venueId, setVenueId] = useState("");
  const [startsAt, setStartsAt] = useState("");
  const [endsAt, setEndsAt] = useState("");
  const [workstations, setWorkstations] = useState("10");
  const [sessionOut, setSessionOut] = useState<ScheduleSessionOut | null>(null);

  const [sessionId, setSessionId] = useState("");
  const [competitorId, setCompetitorId] = useState("");
  const [workstation, setWorkstation] = useState("");
  const [assignOut, setAssignOut] = useState<ScheduleAssignmentOut | null>(null);

  const [incidentSummary, setIncidentSummary] = useState("");
  const [severity, setSeverity] = useState("");
  const [incidentOut, setIncidentOut] = useState<ScheduleIncidentOut | null>(
    null,
  );

  function captureErr(err: unknown, fallback: string) {
    if (err instanceof ApiError) {
      setError(err);
      setFieldErrors(fieldErrorMap(err.fields));
    } else {
      setError(
        new ApiError(0, {
          error: {
            code: "HTTP_ERROR",
            message: fallback,
            fields: [],
            traceId: "",
          },
        }),
      );
    }
  }

  async function onCreateSession(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setFieldErrors({});
    setPending(true);
    setStatusMessage(null);
    try {
      const out = await createScheduleSession(competitionId, {
        venueId: venueId.trim(),
        startsAt: new Date(startsAt).toISOString(),
        endsAt: new Date(endsAt).toISOString(),
        workstations: Number(workstations),
      });
      setSessionOut(out);
      setSessionId(out.sessionId);
      setStatusMessage(`Session created (${out.state}).`);
    } catch (err) {
      setSessionOut(null);
      captureErr(err, "Could not create session");
    } finally {
      setPending(false);
    }
  }

  async function onAssign(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setFieldErrors({});
    setPending(true);
    setStatusMessage(null);
    try {
      const out = await assignScheduleSlot(sessionId.trim(), {
        competitorId: competitorId.trim(),
        workstation: workstation.trim(),
      });
      setAssignOut(out);
      setStatusMessage(`Assigned workstation ${out.workstation}.`);
    } catch (err) {
      setAssignOut(null);
      captureErr(err, "Could not assign workstation");
    } finally {
      setPending(false);
    }
  }

  async function onIncident(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setFieldErrors({});
    setPending(true);
    setStatusMessage(null);
    try {
      const out = await recordScheduleIncident(sessionId.trim(), {
        summary: incidentSummary.trim(),
        severity: severity.trim() || null,
      });
      setIncidentOut(out);
      setStatusMessage(`Incident recorded at ${new Date(out.recordedAt).toLocaleString()}.`);
    } catch (err) {
      setIncidentOut(null);
      captureErr(err, "Could not record incident");
    } finally {
      setPending(false);
    }
  }

  return (
    <PageShell width="narrow" className="space-y-6">
      <PageHeader
        title="Physical-stage schedule"
        description="Create sessions, assign competitors to workstations, and record on-site incidents."
      />

      <p className="text-sm text-muted-foreground">
        Competition <span className="font-mono">{competitionId}</span>
      </p>

      {statusMessage ? (
        <Alert data-testid="schedule-status-message">
          <AlertTitle>Status</AlertTitle>
          <AlertDescription>{statusMessage}</AlertDescription>
        </Alert>
      ) : null}

      <ApiErrorAlert error={error} />

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Create session</CardTitle>
          <CardDescription>
            Venue and workstation capacity come from cycle configuration /
            venue records.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={onCreateSession} className="space-y-4" noValidate>
            <div className="space-y-2">
              <Label htmlFor="venueId">Venue ID</Label>
              <Input
                id="venueId"
                className="min-h-11"
                value={venueId}
                onChange={(e) => setVenueId(e.target.value)}
                required
                data-testid="schedule-venue-id"
              />
              <FieldMessage message={fieldErrors.venueId} />
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label htmlFor="startsAt">Starts at</Label>
                <Input
                  id="startsAt"
                  type="datetime-local"
                  className="min-h-11"
                  value={startsAt}
                  onChange={(e) => setStartsAt(e.target.value)}
                  required
                  data-testid="schedule-starts"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="endsAt">Ends at</Label>
                <Input
                  id="endsAt"
                  type="datetime-local"
                  className="min-h-11"
                  value={endsAt}
                  onChange={(e) => setEndsAt(e.target.value)}
                  required
                  data-testid="schedule-ends"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="workstations">Workstations</Label>
              <Input
                id="workstations"
                type="number"
                min={1}
                className="min-h-11"
                value={workstations}
                onChange={(e) => setWorkstations(e.target.value)}
                required
                data-testid="schedule-workstations"
              />
            </div>
            <Button
              type="submit"
              className="min-h-11 w-full"
              disabled={pending}
              data-testid="schedule-create"
            >
              Create session
            </Button>
          </form>
          {sessionOut ? (
            <Alert className="mt-4" data-testid="schedule-session-result">
              <AlertTitle className="flex items-center gap-2">
                Session <StatusBadge status={sessionOut.state} />
              </AlertTitle>
              <AlertDescription>
                <span className="font-mono text-xs" data-testid="schedule-session-id">
                  {sessionOut.sessionId}
                </span>
                {" · "}
                {sessionOut.workstations} workstations
              </AlertDescription>
            </Alert>
          ) : null}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Assign workstation</CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={onAssign} className="space-y-4" noValidate>
            <div className="space-y-2">
              <Label htmlFor="sessionId">Session ID</Label>
              <Input
                id="sessionId"
                className="min-h-11"
                value={sessionId}
                onChange={(e) => setSessionId(e.target.value)}
                required
                data-testid="schedule-assign-session"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="competitorId">Competitor ID</Label>
              <Input
                id="competitorId"
                className="min-h-11"
                value={competitorId}
                onChange={(e) => setCompetitorId(e.target.value)}
                required
                data-testid="schedule-competitor"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="workstation">Workstation</Label>
              <Input
                id="workstation"
                className="min-h-11"
                value={workstation}
                onChange={(e) => setWorkstation(e.target.value)}
                required
                data-testid="schedule-workstation"
              />
            </div>
            <Button
              type="submit"
              className="min-h-11 w-full"
              disabled={pending}
              data-testid="schedule-assign"
            >
              Assign
            </Button>
          </form>
          {assignOut ? (
            <Alert className="mt-4" data-testid="schedule-assign-result">
              <AlertTitle>Assigned</AlertTitle>
              <AlertDescription>
                {assignOut.workstation} · readiness {assignOut.readiness}
              </AlertDescription>
            </Alert>
          ) : null}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Record incident</CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={onIncident} className="space-y-4" noValidate>
            <div className="space-y-2">
              <Label htmlFor="incidentSummary">Summary</Label>
              <Textarea
                id="incidentSummary"
                value={incidentSummary}
                onChange={(e) => setIncidentSummary(e.target.value)}
                required
                rows={3}
                data-testid="schedule-incident-summary"
              />
              <FieldMessage message={fieldErrors.summary} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="severity">Severity (optional)</Label>
              <Input
                id="severity"
                className="min-h-11"
                value={severity}
                onChange={(e) => setSeverity(e.target.value)}
                data-testid="schedule-incident-severity"
              />
            </div>
            <Button
              type="submit"
              variant="outline"
              className="min-h-11 w-full"
              disabled={pending}
              data-testid="schedule-incident"
            >
              Record incident
            </Button>
          </form>
          {incidentOut ? (
            <Alert className="mt-4" data-testid="schedule-incident-result">
              <AlertTitle>Incident recorded</AlertTitle>
              <AlertDescription>
                <span className="font-mono text-xs">{incidentOut.incidentId}</span>
              </AlertDescription>
            </Alert>
          ) : null}
        </CardContent>
      </Card>

      <p className="text-xs text-muted-foreground">
        <Link
          href={`/admin/competitions/${competitionId}`}
          className="underline underline-offset-2"
        >
          Back to cycle workspace
        </Link>
      </p>
    </PageShell>
  );
}
